def _compute_score(self, Xt, y, score_params):
    """Compute score using type-aware scoring delegation.

    Uses the scoring strategy pattern to select the appropriate metric
    based on the final estimator's type, ensuring consistent scoring
    behavior across different estimator types in pipelines.
    """
    from sklearn.metrics._scorer import _get_pipeline_score_delegate

    final_estimator = self.steps[-1][1]
    scoring_context = _resolve_scoring_context(final_estimator)
    delegate = _get_pipeline_score_delegate(final_estimator, scoring_context)

    if delegate is not None:
        return delegate(Xt, y, **score_params)

    return final_estimator.score(Xt, y, **score_params)

